update public.servicios set descripcion =
  'No soy programadora: esta web la armé con inteligencia artificial. Te acompaño a hacer la tuya de la misma forma, con ventas, cobros, agenda y mails automáticos, resolviendo juntos cada paso con IA. Pagás una sola vez y tenés todas las reuniones que hagan falta hasta que tu web quede funcionando, más acceso ilimitado a todos los ebooks.'
where id = 'web-automatizada';
